'use strict';
// Isolated design study. No localStorage, API calls, or changes to the user's app.
const directions = {
  vokiri:{name:'vokiri',pronunciation:'воки́ри',title:'Английский как личное пространство.',description:'Главная даёт обзор. Человек сам выбирает: повторить слова или открыть историю.',entry:'Две крупные карточки: повторение и чтение.',navigation:'Постоянная нижняя навигация. Можно свободно менять занятие.',reading:'Мягкая карточка заголовка, уровень рядом с текстом, слова как метки.',tradeoff:'Легко ориентироваться, но перед началом нужно выбрать действие.',voice:'«Сегодня достаточно. Хотите ещё — продолжим».',tagline:'Words become yours.',palette:['#262c20','#d6f477','#f3f3ed','#637239'],mark:'<path d="M12 13 26 48 40 13M39 34l8-21" fill="none" stroke="currentColor" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/>',logo:'Открытая v и повторный штрих. Мягкая геометрия, большие радиусы, спокойный ритм.'},
  rekio:{name:'rekio',pronunciation:'ре́кио',title:'Одно действие. Потом следующее.',description:'Главная — начало занятия. Короткий маршрут ведёт от вспоминания к встрече слова в истории.',entry:'Одна большая кнопка «Начать». Остальные действия вторичны.',navigation:'Линейная сессия с выходом в любой момент. Следующий шаг всегда рядом.',reading:'Полноэкранный текст после карточек. Уровень — компактный переключатель.',tradeoff:'Меньше решений перед стартом, но обзор словаря уходит на второй план.',voice:'«Вспомнили. Теперь встретим слово в истории».',tagline:'Make it familiar.',palette:['#17191e','#ff876d','#f5f6fa','#454954'],mark:'<path d="M12 45V12h17a12 12 0 0 1 0 24H12m18 0 14 12" fill="none" stroke="currentColor" stroke-width="6" stroke-linejoin="round"/><path d="m30 7 8 5-8 5" fill="none" stroke="currentColor" stroke-width="3"/>',logo:'Монограмма r с возвращающимся штрихом. Плотные заголовки, прямые панели, коралловое действие.'},
  vekri:{name:'vekri',pronunciation:'ве́кри',title:'Ваш английский — личный журнал.',description:'История становится входом в продукт. Слова живут рядом с чтением, а повторение — на следующей странице.',entry:'Заголовок истории, короткий анонс и заметки из словаря.',navigation:'Читать, возвращаться к словам, открывать следующий выпуск. Меньше панелей и карточек.',reading:'Редакционная колонка, засечки, подчёркивания и переводы на полях.',tradeoff:'Выразительно и удобно для чтения; привычку повторять придётся поддерживать заметным приглашением.',voice:'«Вы уже встречали эти слова. Сегодня — в другой истории».',tagline:'Read your words into life.',palette:['#222a43','#2346c8','#fcfcf8','#d5d8e0'],mark:'<path d="M13 10v35h31M22 10v26h22" fill="none" stroke="currentColor" stroke-width="3"/><path d="M30 13h15M30 21h11" fill="none" stroke="currentColor" stroke-width="3"/>',logo:'Два смещённых поля и строки. Курсивный словесный знак, белая бумага, синие пометки.'}
};
const exampleWords=[
 {word:'reluctant',translation:'неохотный; не решающийся',example:'Mia was reluctant to speak at the meeting.'},
 {word:'confidence',translation:'уверенность',example:'A small success gave her confidence.'},
 {word:'opportunity',translation:'возможность',example:'The next meeting was an opportunity to try again.'}
];
// Authored fragments for evaluating layout and level changes, never presented as AI output.
const levelExamples={
 A2:{title:'One small step',description:'Короткие предложения. Сложные целевые слова объясняются.',text:'Mia has an idea at work. But she is reluctant to speak. She does not want to make a mistake. Her friend asks her to share the idea. Mia says a few words. Her team listens. This gives her confidence: she feels she can do it. The next meeting is an opportunity — a chance to try again.'},
 B1:{title:'One small step',description:'Связный рассказ. Причины и последствия выражены явно.',text:'Although Mia had a useful idea at work, she was reluctant to share it because she was afraid of making a mistake. A friend encouraged her to say a few words, and the team listened carefully. Their response gave her confidence. She began to see the next meeting as an opportunity to contribute rather than something to worry about.'},
 B2:{title:'One small step',description:'Более сложный синтаксис, нюансы и менее прямые пояснения.',text:'Reluctant to expose an unfinished idea to criticism, Mia initially kept quiet at work. Encouraged by a colleague, however, she offered a brief suggestion, which the team considered with interest. The experience strengthened her confidence without entirely removing her doubts. What had seemed like a test of her competence became an opportunity to contribute, even before she felt fully prepared.'}
};
let designState={direction:'vokiri',screen:'home',level:'A2',index:0,revealed:false,ratings:[]};
const select=s=>document.querySelector(s);
function mark(id){return `<svg viewBox="0 0 56 56" aria-hidden="true">${directions[id].mark}</svg>`}
function nav(){const labels=designState.direction==='vekri'?['Выпуск','Слова','Читать']:designState.direction==='rekio'?['Сегодня','Практика','История']:['Сегодня','Повторить','Читать'];return `<nav class="app-nav" aria-label="Навигация макета">${['home','review','reading'].map((s,i)=>`<button data-screen="${s}" ${designState.screen===s?'aria-current="page"':''}>${labels[i]}</button>`).join('')}</nav>`}
function header(){return designState.direction==='vekri'?`<header class="app-head"><div class="app-logo">${mark('vekri')}vekri</div><div class="journal-edition">ЛИЧНЫЙ АНГЛИЙСКИЙ / ВЫПУСК 01</div></header>`:`<header class="app-head"><div class="app-logo">${mark(designState.direction)}${designState.direction}</div><span class="avatar" aria-label="Пример профиля">KS</span></header>`}
function home(){
 if(designState.direction==='vokiri')return `<div class="kicker">Среда, 9 сентября</div><h1 class="big-title">A little English,<br>every day.</h1><div class="dashboard-cards"><section class="daily-card"><span class="kicker">Пора встретиться снова</span><div class="number">12<span>слов сегодня</span></div><p>Небольшая сессия в своём темпе.</p><button class="primary-action" data-screen="review">Повторить слова <span>↗</span></button></section><section class="story-card"><span class="kicker">История для вас</span><h2>One small step</h2><p>Как решиться высказать свою идею.</p><div><span class="reading-meta">${designState.level} · 3 ваших слова</span><button data-screen="reading" aria-label="Открыть историю">↗</button></div></section></div>`;
 if(designState.direction==='rekio')return `<div class="focus-home"><div class="focus-route"><b>01 ВСПОМНИТЬ</b><span>/</span><span>02 ВСТРЕТИТЬ В ТЕКСТЕ</span></div><h1 class="big-title">Back to<br>your words.</h1><div><div class="focus-count">12</div><p class="focus-caption">слов на сегодня.<br>Начните с одного.</p></div><button class="primary-action" data-screen="review">Начать занятие <span>→</span></button><section class="focus-next"><span>СЛЕДОМ / ЛИЧНАЯ ИСТОРИЯ</span><button data-screen="reading">One small step <span>↗</span></button><p class="reading-meta">Ваши слова в новом контексте.<br>Можно сразу перейти к чтению.</p></section></div>`;
 return `<div class="journal-home"><article class="journal-lead"><span class="kicker">Работа и люди / ${designState.level}</span><h1>One small<br><em>step.</em></h1><p>Иногда несколько слов меняют то, как мы чувствуем себя среди других людей.</p><button data-screen="reading">Читать свою историю ↗</button></article><section class="journal-shelf"><h2>На полях</h2>${exampleWords.map(w=>`<div class="journal-word"><b>${w.word}</b><span>в этой истории</span></div>`).join('')}<p class="example-note">Знакомые слова возвращаются в новом контексте.</p><button class="primary-action" data-screen="review">Вернуться к словам <span>→</span></button></section></div>`;
}
function levels(){return `<div class="level-control" role="group" aria-label="Сложность примера">${Object.keys(levelExamples).map(l=>`<button data-level="${l}" aria-pressed="${designState.level===l}">${l}</button>`).join('')}</div>`}
function reading(){const e=levelExamples[designState.level];const text=e.text.replace(/\b(reluctant|confidence|opportunity)\b/gi,'<mark>$1</mark>');const terms=designState.direction==='vekri'?`<aside class="word-margin"><h3>Ваши слова</h3>${exampleWords.map(w=>`<div class="margin-word"><b>${w.word}</b><span>${w.translation}</span></div>`).join('')}</aside>`:`<div class="target-words">${exampleWords.map(w=>`<span>${w.word}</span>`).join('')}</div>`;return `<div class="back-row"><button class="back-action" data-screen="home" aria-label="На главную макета">←</button><span class="kicker">Работа и люди</span></div>${levels()}<h1 class="reading-title">${e.title}</h1><p class="reading-meta">Тот же сюжет · тот же набор слов<br>${e.description}</p><div class="reading-layout">${terms}<p class="reading-copy">${text}</p></div><div class="reading-footer"><button class="quiet-action" data-action="new-story">Другой текст ↗</button><button class="quiet-action" data-screen="review">Повторить слова →</button></div><p class="example-note">Фрагмент для сравнения уровней и дизайна. В готовом продукте история будет генерироваться под ваш словарь.</p>`}
function review(){if(designState.index>=exampleWords.length)return `<div class="review-result"><span class="kicker">Пример сессии завершён</span><h2>Слова ждут<br>в истории.</h2><p>Один ответ — начало. К этим словам вернёмся через время, а сейчас встретим их в контексте.</p><button class="primary-action" data-screen="reading">Перейти к истории <span>→</span></button><button class="quiet-action" data-action="reset-review">Посмотреть карточки ещё раз</button></div>`;const w=exampleWords[designState.index];return `<div class="back-row"><button class="back-action" data-screen="home" aria-label="Выйти из примера повторения">←</button><span class="review-count">${designState.index+1} / 3 · пример сессии</span></div>${designState.direction==='rekio'?`<div class="focus-progress"><span style="width:${(designState.index+1)/3*100}%"></span></div>`:''}<div class="review-surface"><span class="kicker">Вспомните значение</span><h1 class="review-word">${w.word}</h1>${designState.revealed?`<p class="review-translation">${w.translation}</p><p class="review-example">${w.example}</p>`:'<p class="example-note">Не торопитесь открывать ответ.</p>'}</div>${designState.revealed?`<div class="review-grade"><button data-rating="forgot">Забыл</button><button data-rating="hard">С трудом</button><button data-rating="recalled">Вспомнил</button></div>`:'<button class="primary-action review-show" data-action="reveal">Показать ответ <span>↗</span></button>'}<p class="example-note">Ответ в этом макете не меняет ваш словарь. «Вспомнил» не означает «выучено».</p>`}
function notes(){const d=directions[designState.direction];select('#direction-notes').innerHTML=`<span class="eyebrow">${d.name} / ${d.pronunciation}</span><h2 class="direction-notes-title">${d.title}</h2><p class="direction-description">${d.description}</p><dl class="notes-list">${[['Первый экран',d.entry],['Навигация',d.navigation],['Подача текста',d.reading],['Компромисс',d.tradeoff]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="brand-swatch" aria-label="Цветовая палитра">${d.palette.map(c=>`<span style="background:${c}" title="${c}"></span>`).join('')}</div><div class="brand-lockup">${mark(designState.direction)}<strong>${d.tagline}</strong><p>${d.logo}</p><p>${d.voice}</p></div><p class="brand-caveat">Рабочее имя и эскиз знака. Выбор этого макета не переименовывает приложение.</p>`}
function renderDesign(){notes();const p=select('#product-preview');p.className=`product ${designState.direction}`;p.innerHTML=`${header()}<div class="app-content">${designState.screen==='home'?home():designState.screen==='review'?review():reading()}</div>${nav()}`;document.querySelectorAll('[data-direction]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.direction===designState.direction)));document.querySelectorAll('.preview-toolbar [data-screen]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.screen===designState.screen)))}
function feedback(text){select('#preview-feedback').textContent=text}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.direction&&directions[b.dataset.direction]){designState.direction=b.dataset.direction;renderDesign();feedback('Экран и уровень сохранены, чтобы сравнить подачу одной задачи.');return}
 if(b.dataset.screen&&['home','review','reading'].includes(b.dataset.screen)){designState.screen=b.dataset.screen;renderDesign();feedback('');return}
 if(b.dataset.level&&levelExamples[b.dataset.level]){designState.level=b.dataset.level;renderDesign();feedback('Сохранились Мия, рабочая встреча и три слова. Изменились язык и пояснения.');return}
 if(b.dataset.rating){if(!designState.revealed||designState.index>=exampleWords.length)return;designState.ratings.push({word:exampleWords[designState.index].word,rating:b.dataset.rating});designState.index++;designState.revealed=false;renderDesign();feedback('Ответ отмечен только в примере. Реальный прогресс не изменился.');return}
 if(b.dataset.action==='reveal'){designState.revealed=true;renderDesign();feedback('');return}
 if(b.dataset.action==='reset-review'){designState.index=0;designState.revealed=false;designState.ratings=[];renderDesign();return}
 if(b.dataset.action==='new-story'){select('#scenario-dialog').showModal();return}
 if(b.dataset.action==='close-dialog'){select('#scenario-dialog').close();return}
 if(b.id==='width-toggle'){const wide=select('.preview-stage').classList.toggle('wide');b.setAttribute('aria-pressed',String(wide));b.textContent=wide?'Телефон ↔':'Шире ↔'}
});
const requestedDirection=new URLSearchParams(location.search).get('direction');if(directions[requestedDirection])designState.direction=requestedDirection;
renderDesign();
